-- ============================================================================
-- Proyecto: TecNM SSPP (Servicio Social y Prácticas Profesionales)
-- Archivo: database/design/schema.sql
-- Motor Objetivo: PostgreSQL 16+
--
-- Estándares Técnicos Aplicados:
--   1. Idioma: Inglés técnico para todas las entidades, columnas y constraints.
--   2. Nomenclatura: snake_case estricto.
--   3. Llaves Primarias: BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY.
--   4. Auditoría Estándar (6 campos obligatorios en cada tabla):
--        - created_by BIGINT NULL
--        - updated_by BIGINT NULL
--        - deleted_by BIGINT NULL
--        - created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
--        - updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
--        - deleted_at TIMESTAMP WITH TIME ZONE NULL
--   5. Integridad Referencial: Constraints fk_{origen}__{destino} explícitas
--      con reglas ON UPDATE CASCADE ON DELETE RESTRICT (o SET NULL cuando aplique).
--   6. Indexación: Índices explícitos en todas las llaves foráneas y deleted_at.
--   7. Idempotencia: Bloque transaccional BEGIN...COMMIT con DROP TABLE CASCADE.
-- ============================================================================

BEGIN;

-- ============================================================================
-- 1. ELIMINACIÓN DE TABLAS EN ORDEN INVERSO DE DEPENDENCIAS (IDEMPOTENCIA)
-- ============================================================================
DROP TABLE IF EXISTS internship_evaluations CASCADE;
DROP TABLE IF EXISTS internships CASCADE;
DROP TABLE IF EXISTS social_service_activity_assessments CASCADE;
DROP TABLE IF EXISTS social_service_evaluations CASCADE;
DROP TABLE IF EXISTS social_service_bi_monthly_reports CASCADE;
DROP TABLE IF EXISTS social_service_commitments CASCADE;
DROP TABLE IF EXISTS social_service_applications CASCADE;
DROP TABLE IF EXISTS social_services CASCADE;
DROP TABLE IF EXISTS expedient_documents CASCADE;
DROP TABLE IF EXISTS document_series CASCADE;
DROP TABLE IF EXISTS institutional_authorities CASCADE;
DROP TABLE IF EXISTS company_supervisors CASCADE;
DROP TABLE IF EXISTS companies CASCADE;
DROP TABLE IF EXISTS students CASCADE;
DROP TABLE IF EXISTS student_import_batches CASCADE;
DROP TABLE IF EXISTS academic_periods CASCADE;
DROP TABLE IF EXISTS careers CASCADE;
DROP TABLE IF EXISTS user_roles CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS roles CASCADE;

-- ============================================================================
-- 2. CAPA 1: NÚCLEO COMPARTIDO (SHARED CORE)
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Tabla: roles
-- Catálogo oficial de roles institucionales y perfiles de acceso.
-- ----------------------------------------------------------------------------
CREATE TABLE roles (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name varchar(50) NOT NULL,
    description text NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_roles__name UNIQUE (name)
);

CREATE INDEX idx_roles__name ON roles (name);
CREATE INDEX idx_roles__deleted_at ON roles (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: users
-- Cuentas de usuario institucionales para autenticación local y auditoría.
-- ----------------------------------------------------------------------------
CREATE TABLE users (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username varchar(64) NOT NULL,
    email varchar(254) NOT NULL,
    password_hash varchar(512) NOT NULL,
    name varchar(160) NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_users__username UNIQUE (username),
    CONSTRAINT uq_users__email UNIQUE (email)
);

CREATE INDEX idx_users__username ON users (username);
CREATE INDEX idx_users__email ON users (email);
CREATE INDEX idx_users__deleted_at ON users (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: user_roles
-- Asignación de roles a usuarios con soporte para roles múltiples (N:M).
-- ----------------------------------------------------------------------------
CREATE TABLE user_roles (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id bigint NOT NULL,
    role_id bigint NOT NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_user_roles__user_role UNIQUE (user_id, role_id),
    CONSTRAINT fk_user_roles__users FOREIGN KEY (user_id)
        REFERENCES users (id)
        ON UPDATE CASCADE
        ON DELETE CASCADE,
    CONSTRAINT fk_user_roles__roles FOREIGN KEY (role_id)
        REFERENCES roles (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT
);

CREATE INDEX idx_user_roles__user_id ON user_roles (user_id);
CREATE INDEX idx_user_roles__role_id ON user_roles (role_id);
CREATE INDEX idx_user_roles__deleted_at ON user_roles (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: careers
-- Catálogo oficial de ingenierías y planes de estudio del ITSM.
-- ----------------------------------------------------------------------------
CREATE TABLE careers (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code varchar(16) NOT NULL,
    name varchar(150) NOT NULL,
    total_credits integer NOT NULL DEFAULT 260,
    is_active boolean NOT NULL DEFAULT true,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_careers__code UNIQUE (code),
    CONSTRAINT ck_careers__total_credits CHECK (total_credits > 0)
);

CREATE INDEX idx_careers__code ON careers (code);
CREATE INDEX idx_careers__deleted_at ON careers (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: academic_periods
-- Catálogo de semestres regulares y periodos lectivos.
-- ----------------------------------------------------------------------------
CREATE TABLE academic_periods (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code varchar(32) NOT NULL,
    name varchar(100) NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_academic_periods__code UNIQUE (code),
    CONSTRAINT ck_academic_periods__dates CHECK (start_date <= end_date)
);

CREATE INDEX idx_academic_periods__code ON academic_periods (code);
CREATE INDEX idx_academic_periods__is_active ON academic_periods (is_active);
CREATE INDEX idx_academic_periods__deleted_at ON academic_periods (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: student_import_batches
-- Bitácora y trazabilidad de importaciones masivas de estudiantes desde Excel.
-- ----------------------------------------------------------------------------
CREATE TABLE student_import_batches (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    period_id bigint NOT NULL,
    file_name varchar(255) NOT NULL,
    file_url text NOT NULL,
    total_records integer NOT NULL DEFAULT 0,
    imported_records integer NOT NULL DEFAULT 0,
    failed_records integer NOT NULL DEFAULT 0,
    status varchar(32) NOT NULL DEFAULT 'completed',
    notes text NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_student_import_batches__academic_periods FOREIGN KEY (period_id)
        REFERENCES academic_periods (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_student_import_batches__records CHECK (
        total_records >= 0 AND imported_records >= 0 AND failed_records >= 0
    ),
    CONSTRAINT ck_student_import_batches__status CHECK (
        status IN ('pending', 'processing', 'completed', 'failed')
    )
);

CREATE INDEX idx_student_import_batches__period_id ON student_import_batches (period_id);
CREATE INDEX idx_student_import_batches__deleted_at ON student_import_batches (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: students
-- Expediente central del estudiante, avance reticular, seguro IMSS y semáforo.
-- ----------------------------------------------------------------------------
CREATE TABLE students (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id bigint NULL,
    career_id bigint NOT NULL,
    import_batch_id bigint NULL,
    control_number varchar(32) NOT NULL,
    curp varchar(18) NULL,
    first_surname varchar(70) NOT NULL,
    second_surname varchar(70) NULL,
    first_name varchar(100) NOT NULL,
    gender char(1) NULL,
    institutional_email varchar(255) NULL,
    personal_email varchar(255) NULL,
    phone_number varchar(20) NULL,
    current_semester integer NOT NULL DEFAULT 1,
    completed_credits integer NOT NULL DEFAULT 0,
    curriculum_progress_percentage numeric(5,2) NOT NULL DEFAULT 0.00,
    is_enrolled boolean NOT NULL DEFAULT true,
    has_valid_imss boolean NOT NULL DEFAULT false,
    imss_validity_file_url text NULL,
    imss_validated_at timestamp with time zone NULL,
    imss_validated_by bigint NULL,
    traffic_light_status varchar(32) NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_students__control_number UNIQUE (control_number),
    CONSTRAINT uq_students__user_id UNIQUE (user_id),
    CONSTRAINT fk_students__users FOREIGN KEY (user_id)
        REFERENCES users (id)
        ON UPDATE CASCADE
        ON DELETE SET NULL,
    CONSTRAINT fk_students__careers FOREIGN KEY (career_id)
        REFERENCES careers (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_students__student_import_batches FOREIGN KEY (import_batch_id)
        REFERENCES student_import_batches (id)
        ON UPDATE CASCADE
        ON DELETE SET NULL,
    CONSTRAINT fk_students__imss_validator FOREIGN KEY (imss_validated_by)
        REFERENCES users (id)
        ON UPDATE CASCADE
        ON DELETE SET NULL,
    CONSTRAINT ck_students__gender CHECK (gender IS NULL OR gender IN ('M', 'F')),
    CONSTRAINT ck_students__semester CHECK (current_semester BETWEEN 1 AND 15),
    CONSTRAINT ck_students__credits CHECK (completed_credits >= 0),
    CONSTRAINT ck_students__progress CHECK (curriculum_progress_percentage BETWEEN 0.00 AND 100.00),
    CONSTRAINT ck_students__traffic_light CHECK (
        traffic_light_status IS NULL OR
        traffic_light_status IN ('first_notice', 'second_notice', 'third_notice', 'non_compliant')
    )
);

CREATE INDEX idx_students__control_number ON students (control_number);
CREATE INDEX idx_students__user_id ON students (user_id);
CREATE INDEX idx_students__career_id ON students (career_id);
CREATE INDEX idx_students__import_batch_id ON students (import_batch_id);
CREATE INDEX idx_students__traffic_light_status ON students (traffic_light_status);
CREATE INDEX idx_students__deleted_at ON students (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: companies
-- Padrón de dependencias externas y departamentos internos TecNM receptores.
-- ----------------------------------------------------------------------------
CREATE TABLE companies (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rfc varchar(13) NULL,
    name varchar(200) NOT NULL,
    commercial_name varchar(200) NULL,
    sector varchar(50) NOT NULL DEFAULT 'private',
    is_tecnm_internal boolean NOT NULL DEFAULT false,
    address text NULL,
    city varchar(100) NOT NULL DEFAULT 'Monclova',
    state varchar(100) NOT NULL DEFAULT 'Coahuila',
    phone_number varchar(30) NULL,
    email varchar(255) NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT ck_companies__sector CHECK (sector IN ('public', 'private', 'social', 'education'))
);

CREATE INDEX idx_companies__name ON companies (name);
CREATE INDEX idx_companies__is_tecnm_internal ON companies (is_tecnm_internal);
CREATE INDEX idx_companies__deleted_at ON companies (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: company_supervisors
-- Responsables de programa, tutores o personal de RH en las empresas.
-- ----------------------------------------------------------------------------
CREATE TABLE company_supervisors (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id bigint NOT NULL,
    full_name varchar(180) NOT NULL,
    position varchar(150) NOT NULL,
    email varchar(255) NULL,
    phone_number varchar(30) NULL,
    is_signatory boolean NOT NULL DEFAULT true,
    is_active boolean NOT NULL DEFAULT true,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_company_supervisors__companies FOREIGN KEY (company_id)
        REFERENCES companies (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT
);

CREATE INDEX idx_company_supervisors__company_id ON company_supervisors (company_id);
CREATE INDEX idx_company_supervisors__deleted_at ON company_supervisors (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: institutional_authorities
-- Autoridades y directivos del TecNM para emisión dinámica de documentos.
-- ----------------------------------------------------------------------------
CREATE TABLE institutional_authorities (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_key varchar(64) NOT NULL,
    title varchar(32) NULL,
    full_name varchar(180) NOT NULL,
    position varchar(180) NOT NULL,
    email varchar(255) NULL,
    phone_number varchar(30) NULL,
    signature_initials varchar(16) NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL
);

CREATE INDEX idx_institutional_authorities__role_key ON institutional_authorities (role_key);
CREATE INDEX idx_institutional_authorities__deleted_at ON institutional_authorities (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: document_series
-- Secuencias y folios parametrizables para números de oficio institucionales.
-- ----------------------------------------------------------------------------
CREATE TABLE document_series (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    document_type varchar(64) NOT NULL,
    prefix varchar(20) NOT NULL,
    current_year integer NOT NULL,
    current_sequence integer NOT NULL DEFAULT 0,
    format_pattern varchar(100) NOT NULL DEFAULT '{PREFIX}{SEQ:4}/{DD}/{MM}/{YYYY}',
    description varchar(255) NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_document_series__type_year UNIQUE (document_type, current_year),
    CONSTRAINT ck_document_series__year CHECK (current_year >= 2020),
    CONSTRAINT ck_document_series__sequence CHECK (current_sequence >= 0)
);

CREATE INDEX idx_document_series__type_year ON document_series (document_type, current_year);
CREATE INDEX idx_document_series__deleted_at ON document_series (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: expedient_documents
-- Repositorio de evidencias digitales, constancias y archivos subidos.
-- ----------------------------------------------------------------------------
CREATE TABLE expedient_documents (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id bigint NOT NULL,
    tramite_type varchar(32) NOT NULL,
    tramite_id bigint NULL,
    document_code varchar(64) NOT NULL,
    original_file_name varchar(255) NOT NULL,
    storage_path text NOT NULL,
    file_mime_type varchar(100) NOT NULL DEFAULT 'application/pdf',
    file_size_bytes bigint NOT NULL,
    status varchar(32) NOT NULL DEFAULT 'pending',
    rejection_reason text NULL,
    reviewed_by bigint NULL,
    reviewed_at timestamp with time zone NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_expedient_documents__students FOREIGN KEY (student_id)
        REFERENCES students (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_expedient_documents__reviewer FOREIGN KEY (reviewed_by)
        REFERENCES users (id)
        ON UPDATE CASCADE
        ON DELETE SET NULL,
    CONSTRAINT ck_expedient_documents__tramite CHECK (
        tramite_type IN ('social_service', 'internship', 'general')
    ),
    CONSTRAINT ck_expedient_documents__status CHECK (
        status IN ('pending', 'approved', 'rejected', 'superseded')
    ),
    CONSTRAINT ck_expedient_documents__size CHECK (file_size_bytes > 0)
);

CREATE INDEX idx_expedient_documents__student_id ON expedient_documents (student_id);
CREATE INDEX idx_expedient_documents__reviewed_by ON expedient_documents (reviewed_by);
CREATE INDEX idx_expedient_documents__tramite ON expedient_documents (tramite_type, tramite_id);
CREATE INDEX idx_expedient_documents__status ON expedient_documents (status);
CREATE INDEX idx_expedient_documents__deleted_at ON expedient_documents (deleted_at);

-- ============================================================================
-- 3. CAPA 2: DOMINIO DE SERVICIO SOCIAL
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Tabla: social_services
-- Trámite maestro de Servicio Social (480 horas, min 6 meses, estados).
-- ----------------------------------------------------------------------------
CREATE TABLE social_services (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id bigint NOT NULL,
    period_id bigint NOT NULL,
    company_id bigint NOT NULL,
    supervisor_id bigint NOT NULL,
    presentation_letter_folio varchar(64) NULL,
    presentation_letter_date date NULL,
    program_name varchar(200) NOT NULL,
    program_type varchar(50) NOT NULL,
    modality varchar(20) NOT NULL DEFAULT 'external',
    start_date date NOT NULL,
    end_date date NOT NULL,
    required_hours integer NOT NULL DEFAULT 480,
    accumulated_hours integer NOT NULL DEFAULT 0,
    status varchar(32) NOT NULL DEFAULT 'requested',
    cancellation_reason text NULL,
    termination_letter_folio varchar(64) NULL,
    termination_letter_date date NULL,
    release_certificate_folio varchar(64) NULL,
    released_at timestamp with time zone NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_social_services__students FOREIGN KEY (student_id)
        REFERENCES students (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_social_services__academic_periods FOREIGN KEY (period_id)
        REFERENCES academic_periods (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_social_services__companies FOREIGN KEY (company_id)
        REFERENCES companies (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_social_services__company_supervisors FOREIGN KEY (supervisor_id)
        REFERENCES company_supervisors (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_social_services__program_type CHECK (
        program_type IN (
            'adult_education', 'community_development', 'sports_activities',
            'civic_activities', 'cultural_activities', 'environmental_protection',
            'sustainable_development', 'health_support', 'other'
        )
    ),
    CONSTRAINT ck_social_services__modality CHECK (modality IN ('internal', 'external')),
    CONSTRAINT ck_social_services__dates CHECK (end_date >= start_date),
    CONSTRAINT ck_social_services__required_hours CHECK (required_hours >= 480),
    CONSTRAINT ck_social_services__accumulated_hours CHECK (accumulated_hours >= 0),
    CONSTRAINT ck_social_services__status CHECK (
        status IN (
            'requested', 'approved', 'accepted', 'active',
            'completed_pending_review', 'released', 'cancelled'
        )
    )
);

CREATE INDEX idx_social_services__student_id ON social_services (student_id);
CREATE INDEX idx_social_services__period_id ON social_services (period_id);
CREATE INDEX idx_social_services__company_id ON social_services (company_id);
CREATE INDEX idx_social_services__supervisor_id ON social_services (supervisor_id);
CREATE INDEX idx_social_services__status ON social_services (status);
CREATE INDEX idx_social_services__deleted_at ON social_services (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: social_service_applications
-- Formato oficial Anexo XVIII (Solicitud formal y dictamen de oficina).
-- ----------------------------------------------------------------------------
CREATE TABLE social_service_applications (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    social_service_id bigint NOT NULL,
    student_address text NOT NULL,
    student_phone varchar(20) NOT NULL,
    period_type varchar(20) NOT NULL,
    current_semester integer NOT NULL,
    dependency_name varchar(200) NOT NULL,
    dependency_head_name varchar(180) NOT NULL,
    dependency_head_position varchar(150) NOT NULL,
    activities_outline text NOT NULL,
    is_accepted_by_office boolean NULL,
    rejection_reason text NULL,
    office_observations text NULL,
    reviewed_by bigint NULL,
    reviewed_at timestamp with time zone NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_ss_applications__service_id UNIQUE (social_service_id),
    CONSTRAINT fk_ss_applications__social_services FOREIGN KEY (social_service_id)
        REFERENCES social_services (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_ss_applications__period_type CHECK (period_type IN ('august_january', 'february_july')),
    CONSTRAINT ck_ss_applications__semester CHECK (current_semester BETWEEN 1 AND 15)
);

CREATE INDEX idx_ss_applications__social_service_id ON social_service_applications (social_service_id);
CREATE INDEX idx_ss_applications__deleted_at ON social_service_applications (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: social_service_commitments
-- Formato oficial Anexo XX (Carta Compromiso según Art. 5° Constitucional).
-- ----------------------------------------------------------------------------
CREATE TABLE social_service_commitments (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    social_service_id bigint NOT NULL,
    student_control_number varchar(32) NOT NULL,
    student_address text NOT NULL,
    student_phone varchar(20) NOT NULL,
    dependency_address text NOT NULL,
    program_supervisor_name varchar(180) NOT NULL,
    commitment_date date NOT NULL,
    city varchar(100) NOT NULL DEFAULT 'Monclova',
    is_signed_by_student boolean NOT NULL DEFAULT true,
    signed_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_ss_commitments__service_id UNIQUE (social_service_id),
    CONSTRAINT fk_ss_commitments__social_services FOREIGN KEY (social_service_id)
        REFERENCES social_services (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT
);

CREATE INDEX idx_ss_commitments__social_service_id ON social_service_commitments (social_service_id);
CREATE INDEX idx_ss_commitments__deleted_at ON social_service_commitments (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: social_service_bi_monthly_reports
-- Formato oficial Anexo XXII (Exactamente 3 entregas de reportes acumulativos).
-- ----------------------------------------------------------------------------
CREATE TABLE social_service_bi_monthly_reports (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    social_service_id bigint NOT NULL,
    report_number integer NOT NULL,
    period_start_date date NOT NULL,
    period_end_date date NOT NULL,
    activities_summary text NOT NULL,
    reported_hours integer NOT NULL,
    accumulated_hours integer NOT NULL,
    supervisor_name varchar(180) NOT NULL,
    supervisor_position varchar(150) NOT NULL,
    status varchar(32) NOT NULL DEFAULT 'submitted',
    office_observations text NULL,
    approved_by bigint NULL,
    approved_at timestamp with time zone NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_ss_reports__service_number UNIQUE (social_service_id, report_number),
    CONSTRAINT fk_ss_bi_monthly_reports__social_services FOREIGN KEY (social_service_id)
        REFERENCES social_services (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_ss_reports__number CHECK (report_number IN (1, 2, 3)),
    CONSTRAINT ck_ss_reports__dates CHECK (period_end_date >= period_start_date),
    CONSTRAINT ck_ss_reports__hours CHECK (reported_hours > 0),
    CONSTRAINT ck_ss_reports__acc_hours CHECK (accumulated_hours >= reported_hours),
    CONSTRAINT ck_ss_reports__status CHECK (status IN ('submitted', 'approved', 'rejected'))
);

CREATE INDEX idx_ss_reports__service_number ON social_service_bi_monthly_reports (social_service_id, report_number);
CREATE INDEX idx_ss_reports__status ON social_service_bi_monthly_reports (status);
CREATE INDEX idx_ss_reports__deleted_at ON social_service_bi_monthly_reports (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: social_service_evaluations
-- Formatos oficiales Anexo XXIII (Supervisor) y Anexo XXIV (Autoevaluación Alumno).
-- 7 criterios con escala cualitativa oficial TecNM.
-- ----------------------------------------------------------------------------
CREATE TABLE social_service_evaluations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    social_service_id bigint NOT NULL,
    evaluator_type varchar(20) NOT NULL,
    bimonthly_period varchar(20) NOT NULL DEFAULT 'final',
    criterion_1 varchar(16) NOT NULL,
    criterion_2 varchar(16) NOT NULL,
    criterion_3 varchar(16) NOT NULL,
    criterion_4 varchar(16) NOT NULL,
    criterion_5 varchar(16) NOT NULL,
    criterion_6 varchar(16) NOT NULL,
    criterion_7 varchar(16) NOT NULL,
    evaluator_name varchar(180) NOT NULL,
    evaluator_position varchar(150) NULL,
    observations text NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_ss_evaluations__service_type_period UNIQUE (social_service_id, evaluator_type, bimonthly_period),
    CONSTRAINT fk_ss_evaluations__social_services FOREIGN KEY (social_service_id)
        REFERENCES social_services (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_ss_evaluations__type CHECK (evaluator_type IN ('external_supervisor', 'student_self')),
    CONSTRAINT ck_ss_evaluations__period CHECK (bimonthly_period IN ('1', '2', '3', 'final')),
    CONSTRAINT ck_ss_evaluations__c1 CHECK (criterion_1 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_evaluations__c2 CHECK (criterion_2 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_evaluations__c3 CHECK (criterion_3 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_evaluations__c4 CHECK (criterion_4 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_evaluations__c5 CHECK (criterion_5 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_evaluations__c6 CHECK (criterion_6 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_evaluations__c7 CHECK (criterion_7 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent'))
);

CREATE INDEX idx_ss_evaluations__service_id ON social_service_evaluations (social_service_id);
CREATE INDEX idx_ss_evaluations__deleted_at ON social_service_evaluations (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: social_service_activity_assessments
-- Formato oficial Anexo XXV (Evaluación de impacto social por el prestador).
-- ----------------------------------------------------------------------------
CREATE TABLE social_service_activity_assessments (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    social_service_id bigint NOT NULL,
    question_1 varchar(16) NOT NULL,
    question_2 varchar(16) NOT NULL,
    question_3 varchar(16) NOT NULL,
    question_4 varchar(16) NOT NULL,
    question_5 varchar(16) NOT NULL,
    question_6 varchar(16) NOT NULL,
    question_7 varchar(16) NOT NULL,
    question_8 varchar(16) NOT NULL,
    observations text NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_ss_activity_assessments__service_id UNIQUE (social_service_id),
    CONSTRAINT fk_ss_activity_assessments__social_services FOREIGN KEY (social_service_id)
        REFERENCES social_services (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_ss_act_q1 CHECK (question_1 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_act_q2 CHECK (question_2 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_act_q3 CHECK (question_3 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_act_q4 CHECK (question_4 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_act_q5 CHECK (question_5 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_act_q6 CHECK (question_6 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_act_q7 CHECK (question_7 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent')),
    CONSTRAINT ck_ss_act_q8 CHECK (question_8 IN ('insufficient', 'sufficient', 'good', 'notable', 'excellent'))
);

CREATE INDEX idx_ss_activity_assessments__social_service_id ON social_service_activity_assessments (social_service_id);
CREATE INDEX idx_ss_activity_assessments__deleted_at ON social_service_activity_assessments (deleted_at);

-- ============================================================================
-- 4. CAPA 3: DOMINIO DE PRÁCTICAS PROFESIONALES
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Tabla: internships
-- Trámite maestro de Prácticas Profesionales (200 a 480 horas, 2 créditos).
-- ----------------------------------------------------------------------------
CREATE TABLE internships (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id bigint NOT NULL,
    period_id bigint NOT NULL,
    company_id bigint NOT NULL,
    supervisor_id bigint NOT NULL,
    presentation_letter_folio varchar(64) NULL,
    presentation_letter_date date NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    schedule_description varchar(150) NOT NULL,
    required_hours integer NOT NULL DEFAULT 480,
    completed_hours integer NOT NULL DEFAULT 0,
    status varchar(32) NOT NULL DEFAULT 'requested',
    credits_awarded integer NOT NULL DEFAULT 2,
    cancellation_reason text NULL,
    termination_letter_folio varchar(64) NULL,
    termination_letter_date date NULL,
    release_date date NULL,
    released_at timestamp with time zone NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT fk_internships__students FOREIGN KEY (student_id)
        REFERENCES students (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_internships__academic_periods FOREIGN KEY (period_id)
        REFERENCES academic_periods (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_internships__companies FOREIGN KEY (company_id)
        REFERENCES companies (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT fk_internships__company_supervisors FOREIGN KEY (supervisor_id)
        REFERENCES company_supervisors (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_internships__dates CHECK (end_date >= start_date),
    CONSTRAINT ck_internships__required_hours CHECK (required_hours BETWEEN 200 AND 480),
    CONSTRAINT ck_internships__completed_hours CHECK (completed_hours >= 0),
    CONSTRAINT ck_internships__status CHECK (
        status IN (
            'requested', 'approved', 'accepted', 'active',
            'completed_pending_review', 'released', 'cancelled'
        )
    ),
    CONSTRAINT ck_internships__credits CHECK (credits_awarded = 2)
);

CREATE INDEX idx_internships__student_id ON internships (student_id);
CREATE INDEX idx_internships__period_id ON internships (period_id);
CREATE INDEX idx_internships__company_id ON internships (company_id);
CREATE INDEX idx_internships__supervisor_id ON internships (supervisor_id);
CREATE INDEX idx_internships__status ON internships (status);
CREATE INDEX idx_internships__deleted_at ON internships (deleted_at);

-- ----------------------------------------------------------------------------
-- Tabla: internship_evaluations
-- Formato oficial Anexo XVII (Evaluación al desempeño: PRODUCTIVIDAD LABORAL).
-- 7 criterios numéricos (0 a 4), promedio y nivel de desempeño.
-- ----------------------------------------------------------------------------
CREATE TABLE internship_evaluations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    internship_id bigint NOT NULL,
    activity_name varchar(100) NOT NULL DEFAULT 'PRODUCTIVIDAD LABORAL',
    evaluation_start_date date NOT NULL,
    evaluation_end_date date NOT NULL,
    criterion_1 integer NOT NULL,
    criterion_2 integer NOT NULL,
    criterion_3 integer NOT NULL,
    criterion_4 integer NOT NULL,
    criterion_5 integer NOT NULL,
    criterion_6 integer NOT NULL,
    criterion_7 integer NOT NULL,
    numerical_average numeric(3,2) NOT NULL,
    performance_level varchar(32) NOT NULL,
    is_competency_achieved boolean NOT NULL,
    evaluator_name varchar(180) NOT NULL,
    evaluator_position varchar(150) NOT NULL,
    evaluator_signature_date date NOT NULL,
    observations text NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    deleted_by bigint NULL,
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp with time zone NULL,
    CONSTRAINT uq_internship_evaluations__internship_id UNIQUE (internship_id),
    CONSTRAINT fk_internship_evaluations__internships FOREIGN KEY (internship_id)
        REFERENCES internships (id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT,
    CONSTRAINT ck_internship_eval__dates CHECK (evaluation_end_date >= evaluation_start_date),
    CONSTRAINT ck_internship_eval__c1 CHECK (criterion_1 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c2 CHECK (criterion_2 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c3 CHECK (criterion_3 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c4 CHECK (criterion_4 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c5 CHECK (criterion_5 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c6 CHECK (criterion_6 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__c7 CHECK (criterion_7 BETWEEN 0 AND 4),
    CONSTRAINT ck_internship_eval__avg CHECK (numerical_average BETWEEN 0.00 AND 4.00),
    CONSTRAINT ck_internship_eval__level CHECK (
        performance_level IN ('excellent', 'notable', 'good', 'sufficient', 'insufficient')
    )
);

CREATE INDEX idx_internship_evaluations__internship_id ON internship_evaluations (internship_id);
CREATE INDEX idx_internship_evaluations__deleted_at ON internship_evaluations (deleted_at);

COMMIT;
